function summaryBlankClass(answer=''){
  const len=String(answer).replace(/[\s.,:;()]/g,'').length;
  return len<=4?'short':(len<=10?'medium':'long');
}

function summaryMathify(s=''){
  return String(s).split(/(§§BLANK_(?:SHORT|MEDIUM|LONG)§§)/g).map(part=>{
    const m=/^§§BLANK_(SHORT|MEDIUM|LONG)§§$/.exec(part);
    if(m) return \`<span class=\"summary-blank summary-blank-\${m[1].toLowerCase()}\" aria-label=\"מקום להשלמה\"></span>\`;
    return mathify(part);
  }).join('');
}

function completionRule(rule=''){
  let source=String(rule||'').trim();
  const math=[];
  source=source.replace(/\`[^\`]*\`/g,token=>\`§§MATH_\${math.push(token)-1}§§\`);
  let blanks=0;
  for(const phrase of SUMMARY_KEY_PHRASES){
    if(blanks>=2) break;
    if(!source.includes(phrase)) continue;
    source=source.replace(phrase,\`§§BLANK_\${summaryBlankClass(phrase).toUpperCase()}§§\`);
    blanks++;
  }
  if(blanks===0 && math.length){
    source=source.replace('§§MATH_0§§','§§BLANK_MEDIUM§§');
    blanks=1;
  }
  if(blanks===0){
    const match=[...source.matchAll(/[א-ת]{4,}/g)].at(-1);
    if(match){
      const word=match[0];
      source=source.slice(0,match.index)+\`§§BLANK_\${summaryBlankClass(word).toUpperCase()}§§\`+source.slice(match.index+word.length);
      blanks=1;
    }
  }
  source=source.replace(/§§MATH_(\d+)§§/g,(_,i)=>math[Number(i)]||'');
  return source;
}

function renderCompletionSummary(p){
  const completion=completionRule(p.summary || p.rule || '');
  return \`<section class=\"rule-card completion-summary\" data-summary-completion=\"true\"><strong class=\"summary-label\">השלימו:</strong><div class=\"completion-sentence\">\${summaryMathify(completion)}</div></section>\`;
}

